        function createSmallArc(r, a1, a2) {
          // compute for an arc of the same angle, but centered around the x-axis
          var
          a = (a2 - a1) / 2.0,

          x4 = r * Math.cos(a),
          y4 = r * Math.sin(a),
          x1 = x4,
          y1 = -y4,

          q1 = x1 * x1 + y1 * y1,
          q2 = q1 + x1 * x4 + y1 * y4,
          k2 = 4/3 * (Math.sqrt(2 * q1 * q2) - q2) / (x1 * y4 - y1 * x4),

          x2 = x1 - k2 * y1,
          y2 = y1 + k2 * x1,
          x3 = x2,
          y3 = -y2,

          ar = a + a1,
          cos_ar = Math.cos(ar),
          sin_ar = Math.sin(ar);

